import React, { useEffect, useRef, useState } from 'react';
import { ArrowLeft, ArrowRight, CalendarDays, Check, ChevronLeft, ChevronRight, Download, Droplets, Grape, Leaf, Pencil, Plus, Trash2, Users, X } from 'lucide-react';
import { money, number, parseDate, shortDate } from './data';
import { VARIETIES, costOf, entryKinds, isoWeek, localDate, numeric, saleValues, stats, valveName } from './vineyard';
import './vineyard.css';
import ValveSelectors, { scopeFor } from './ValveSelectors';
import { PETROLINA, useWeather, WeatherIcon, describeWeather } from './Weather';
