const statusOptions = ['Realizado', 'Planejado'];
const inputTypes = ['Mudas', 'Fertilizantes', 'Defensivos', 'Substrato', 'Corretivos', 'Outros'];
const varieties = ['Todas', ...VARIETIES];
const valNumber = valve => `V.${String(valve.number).padStart(2, '0')}`;
const numFields = ['quantity', 'unitPrice', 'amount', 'hours', 'days', 'rate', 'kilograms', 'bunches', 'boxes', 'discountPercent', 'receivedAmount', 'extra', 'commission', 'breakMinutes', 'plantQuantity', 'area'];
const costKinds = ['input', 'fertilization', 'material', 'water', 'labor', 'service', 'diesel'];
function Field({ label, name, type = 'text', required = false, ...props }) {
  return <label className="v-field">{label}<input aria-label={label} name={name} type={type} required={required} {...(type === 'number' ? { min: 0, max: 1e12, step: 'any' } : { maxLength: 160 })} {...props} /></label>;
}
function Select({ label, name, values, ...props }) {
  return <label className="v-field">{label}<select aria-label={label} name={name} {...props}>{values.map(item => typeof item === 'string' ? <option key={item}>{item}</option> : <option key={item.value} value={item.value}>{item.label}</option>)}</select></label>;
}
function Dialog({ title, onClose, children, wide = false }) {
  const ref = useRef(null);
  useEffect(() => { const previous = document.activeElement; ref.current.showModal(); return () => previous?.focus(); }, []);
  return <dialog className={`modal v-dialog ${wide ? 'v-wide' : ''}`} ref={ref} onCancel={e => { e.preventDefault(); onClose(); }} aria-labelledby="v-dialog-title"><div className="modal-header"><h2 id="v-dialog-title">{title}</h2><button className="icon-button" aria-label="Fechar" onClick={onClose}><X size={18} /></button></div>{children}</dialog>;
}
function downloadJSON(model) {
  const url = URL.createObjectURL(new Blob([JSON.stringify({ version: 1, exportedAt: new Date().toISOString(), vineyard: model }, null, 2)], { type: 'application/json' }));
  const a = document.createElement('a'); a.href = url; a.download = `vr-control-lotes-${localDate()}.json`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function exportTable(rows, filename) {
  if (!rows.length) return;
  const keys = Object.keys(rows[0]);
  const escape = value => `"${(typeof value === 'number' ? value.toLocaleString('pt-BR', { useGrouping: false, maximumFractionDigits: 6 }) : String(value ?? '')).replace(/^[=+@-]/, "'$&").replaceAll('"', '""')}"`;
  const csv = '\uFEFF' + [keys.map(escape).join(';'), ...rows.map(row => keys.map(k => escape(row[k])).join(';'))].join('\r\n');
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' }));
  const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function dayShift(value, offset) { const d = parseDate(value); d.setDate(d.getDate() + offset); return localDate(d); }
function Kpis({ items }) { return <div className="v-kpis">{items.map(([label, value]) => <div className="panel v-kpi" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>; }

export default function VineyardWorkspace({ view = 'harvest', model, onChange, onLegacy, newRequest = 0, onNewConsumed, globalQuery = '', weatherLocation = PETROLINA, onEmployeeProfile, onGeneralEdit, onPayrollEdit, focusEntryId, focusValveId, onFocusConsumed, newValveId, hideActivity = false, legacyActivity = [] }) {
  const [lot, setLot] = useState('Todos');
  const [variety, setVariety] = useState('Todas');
  const [selectedId, setSelectedId] = useState(null);
  const [tab, setTab] = useState('Resumo');
  const [editor, setEditor] = useState(null);
  const [period, setPeriod] = useState('');
  const [employeeId, setEmployeeId] = useState('Todos');
  const [employeeType, setEmployeeType] = useState('Todos');
  const [notice, setNotice] = useState('');
  const [reportValveId, setReportValveId] = useState('');
  const importRef = useRef(null);
  const detailRef = useRef(null);
  useEffect(() => { if (selectedId) requestAnimationFrame(() => detailRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })); }, [selectedId]);
  useEffect(() => { setSelectedId(null); setTab('Resumo'); setEditor(null); setPeriod(''); setEmployeeId('Todos'); setEmployeeType('Todos'); }, [view]);
  useEffect(() => { if (newRequest) { setEditor({ kind: view === 'costs' ? 'service' : view === 'planting' ? 'planting' : view === 'fruit' ? 'sale' : view === 'water' ? 'water' : view === 'fertilization' ? 'fertilization' : view === 'payroll' ? 'labor' : view === 'employees' ? 'employee' : 'harvest', valveId: newValveId || undefined }); onNewConsumed?.(); } }, [newRequest]);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(''), 4500); return () => clearTimeout(timer); }, [notice]);
  useEffect(() => { if (focusEntryId) { const row = model.entries.find(e => e.id === focusEntryId); if (row) setEditor({ kind: row.kind, entry: row }); onFocusConsumed?.(); } if (focusValveId) { setSelectedId(focusValveId); setTab('Resumo'); onFocusConsumed?.(); } }, [focusEntryId, focusValveId]);
  const selected = model.valves.find(v => v.id === selectedId);
  const filteredValves = model.valves.filter(v => (lot === 'Todos' || v.lot === lot) && (variety === 'Todas' || v.variety === variety || (view === 'planting' && model.entries.some(e => e.valveId === v.id && e.kind === 'planting' && e.variety === variety))) && (!globalQuery || `${valveName(v)} ${v.variety}`.toLowerCase().includes(globalQuery.toLowerCase())));
  const ids = new Set(filteredValves.map(v => v.id));
  const records = model.entries.filter(e => (ids.has(e.valveId) || (view === 'costs' && !e.valveId && (lot === 'Todos' || e.lot === lot))) && (view !== 'planting' || variety === 'Todas' || (e.variety || model.valves.find(v => v.id === e.valveId)?.variety) === variety) && (!period || e.date.startsWith(period)));
  const totals = stats(records);
  const valveEntries = selected ? model.entries.filter(e => e.valveId === selected.id).sort((a, b) => b.date.localeCompare(a.date)) : [];
  const valveStats = stats(valveEntries);
  const latestPlanting = valveEntries.find(e => e.kind === 'planting');
  const harvestForecast = latestPlanting?.expectedHarvestDate || selected?.harvestDate;
  function openValve(id) { setSelectedId(id); setTab('Resumo'); }
  function saveEntry(entry, crew, plantingInputs) {
    onChange(previous => {
      const id = entry.id || crypto.randomUUID();
      entry = { ...entry, lot: previous.valves.find(v => v.id === entry.valveId)?.lot, variety: entry.variety || previous.valves.find(v => v.id === entry.valveId)?.variety };
      let entries = previous.entries.filter(e => e.id !== id && !(crew && e.groupId === id));
      entries.push({ ...entry, id });
      if (plantingInputs) entries.push(...plantingInputs.map(input => ({ ...input, id: input.id || crypto.randomUUID(), groupId: id, lot: entry.lot, valveId: entry.valveId, date: entry.date, variety: entry.variety, kind: 'input', source: 'planting', status: entry.status })));
      if (crew) entries.push(...crew.map(row => ({ ...row, id: row.id || crypto.randomUUID(), groupId: id, lot: entry.lot, valveId: entry.valveId, date: entry.date, kind: 'labor', name: row.name || 'Equipe de Colheita', job: row.job || (entry.kind === 'planting' ? 'Plantio' : 'Colheita'), source: entry.kind, variety: entry.variety, status: entry.status })));
      return { ...previous, entries };
    }); setEditor(null); setNotice('Registro salvo e vinculado à válvula correta.');
  }
  function saveEmployee(row) { onChange(p => ({ ...p, employees: [...p.employees.filter(e => e.id !== row.id), { ...row, id: row.id || crypto.randomUUID() }] })); setEditor(null); setNotice('Cadastro salvo.'); }
  function deleteEntry(entry) { onChange(p => ({ ...p, entries: p.entries.filter(e => e.id !== entry.id && e.groupId !== entry.id) })); setEditor(null); setNotice('Registro removido e totais recalculados.'); }
  const actions = (kind, label) => <button className="primary" onClick={() => setEditor({ kind, valveId: selected?.id })}><Plus size={16} />{label}</button>;
  const titles = { costs: ['Serviços e Custos', 'Poda, amarrio, diesel e despesas da fazenda. Escolha Geral quando o custo não for rateado.'], planting: ['Plantio', 'Calendário, previsão de colheita, insumos e equipe vinculados a cada válvula.'], harvest: ['Planilha de Colheita', 'Lotes, válvulas e diário interno da produção de uvas.'], fertilization: ['Calendário de Adubação', 'Planeje aplicações e acompanhe o custo realizado por válvula.'], water: ['Água', 'Irrigação, volume e custo de água por lote e válvula.'], fruit: ['Vendas', 'Compradores, previsão de pagamento e confirmação de recebimento.'], employees: ['Colaboradores', 'Cadastro e histórico dos profissionais fixos e avulsos.'], payroll: ['Folhas de Funcionários', 'Horas, diárias, meia diária e faltas por profissional e período.'], reports: ['Relatórios por Lote e Válvula', 'Custos, produção e vendas sem misturar as válvulas dos lotes.'] };
  const title = titles[view] || titles.harvest;
  const activeEmployees = model.employees.filter(e => e.active !== false);
  const laborRows = records.filter(e => e.kind === 'labor' && (employeeId === 'Todos' || e.employeeId === employeeId) && (employeeType === 'Todos' || (e.employeeType || model.employees.find(p => p.id === e.employeeId)?.type) === employeeType));
  const employeeRows = model.employees.filter(e => (employeeType === 'Todos' || e.type === employeeType) && (!globalQuery || e.name.toLowerCase().includes(globalQuery.toLowerCase())));
  const saleRows = records.filter(e => e.kind === 'sale');
  function exportSales() {
    exportTable(saleRows.map(row => { const v = model.valves.find(v => v.id === row.valveId); const sale = saleValues(row); return {
      Entrada: row.date, Semana: isoWeek(row.date), Comprador: row.buyer, 'Nº NF': row.invoice,
      Lote: v.lot, Válvula: v.number, Variedade: row.variety || v.variety, Descrição: row.name,
      Caixas: numeric(row.boxes), 'Quantidade kg': numeric(row.kilograms), Preço: numeric(row.unitPrice), Base: row.priceBasis,
      'Valor Bruto': sale.gross, 'Desconto %': numeric(row.discountPercent), Desconto: sale.discount,
      'Valor Líquido': sale.net, 'M.I / M.E': row.market, Situação: row.status, Pagamento: row.paymentStatus,
      Recebido: sale.received, 'A Receber': sale.outstanding, 'Data do Recebimento': row.paymentDate, Vencimento: row.dueDate,
    }; }), `vr-control-vendas-${localDate()}.csv`);
  }
  function exportPayroll() {
    exportTable(laborRows.map(row => { const v = model.valves.find(v => v.id === row.valveId); const employee = model.employees.find(e => e.id === row.employeeId); return {
      Data: row.date, Nome: employee?.name || row.name, Vínculo: row.employeeType || employee?.type, Função: row.job,
      Lote: v.lot, Válvula: v.number, Presença: row.attendance, Entrada: row.startTime, Saída: row.endTime,
      'Intervalo min': numeric(row.breakMinutes), Horas: numeric(row.hours), Cálculo: row.payMode, Diárias: row.payMode === 'Diária' ? numeric(row.days) : '',
      'Valor Unitário': numeric(row.rate), Extra: numeric(row.extra), Comissão: numeric(row.commission),
      'Valor Apurado': costOf(row), Situação: row.status, Pagamento: row.paymentStatus,
    }; }), `vr-control-folha-${localDate()}.csv`);
  }
  const laborTotals = stats(laborRows);
  function table(rows, compact = false) {
    return <EntryTable rows={rows} model={model} onEdit={entry => entry.linkedPayrollId && onPayrollEdit ? onPayrollEdit(entry.linkedPayrollId) : entry.linkedTransactionId && onGeneralEdit ? onGeneralEdit(entry.linkedTransactionId) : setEditor({ kind: entry.kind, entry })} onDelete={entry => entry.linkedPayrollId && onPayrollEdit ? onPayrollEdit(entry.linkedPayrollId) : entry.linkedTransactionId && onGeneralEdit ? onGeneralEdit(entry.linkedTransactionId) : setEditor({ kind: 'delete', entry })} onValve={id => { setEditor(null); openValve(id); }} compact={compact} />;
  }
  async function importBackup(file) {
    if (!file) return;
    try {
      if (file.size > 50 * 1024 * 1024) throw new Error();
      const parsed = JSON.parse(await file.text()); const backup = parsed.vineyard;
      if (parsed.version !== 1 || !Array.isArray(backup?.valves) || !Array.isArray(backup?.entries) || !Array.isArray(backup?.employees)) throw new Error();
      const known = new Set(model.valves.map(v => v.id));
      if (backup.valves.length !== known.size || new Set(backup.valves.map(v => v.id)).size !== known.size) throw new Error();
      if (backup.valves.some(v => { const original = model.valves.find(old => old.id === v.id); return !original || v.lot !== original.lot || v.number !== original.number || !VARIETIES.includes(v.variety); })) throw new Error();
      const employeeIds = new Set(backup.employees.map(e => e.id));
      if (employeeIds.size !== backup.employees.length || backup.employees.some(e => typeof e.id !== 'string' || !e.id || typeof e.name !== 'string' || !e.name.trim() || !['Fixo', 'Avulso'].includes(e.type))) throw new Error();
      if (new Set(backup.entries.map(e => e.id)).size !== backup.entries.length || backup.entries.some(e => typeof e.id !== 'string' || !e.id || (!known.has(e.valveId) && !(['service', 'diesel', 'material'].includes(e.kind) && !e.valveId)) || !Object.hasOwn(entryKinds, e.kind) || typeof e.name !== 'string' || (e.notes != null && typeof e.notes !== 'string') || !['Planejado', 'Realizado'].includes(e.status) || !/^\d{4}-\d{2}-\d{2}$/.test(e.date) || localDate(parseDate(e.date)) !== e.date || (e.kind === 'labor' && !employeeIds.has(e.employeeId)) || numFields.some(k => k in e && (!Number.isFinite(Number(e[k])) || Number(e[k]) < 0)))) throw new Error();
      for (const key of ['visits', 'attendance', 'absences', 'payrolls', 'employeeHistory', 'activity']) if (backup[key] != null && !Array.isArray(backup[key])) throw new Error();
      if (backup.generalTransactions != null && (!Array.isArray(backup.generalTransactions) || backup.generalTransactions.some(t => typeof t.id !== 'string' || typeof t.name !== 'string' || !['Receita', 'Despesa'].includes(t.type) || !Number.isFinite(Number(t.amount))))) throw new Error();
      if (backup.inventory != null && !Array.isArray(backup.inventory)) throw new Error();
      setEditor({ kind: 'import', backup });
    } catch { setNotice('Arquivo de backup inválido. Nenhum dado foi alterado.'); }
    finally { if (importRef.current) importRef.current.value = ''; }
  }
  return <div className="vineyard-workspace">
    <div className="detail-hero"><div className="module-icon large green">{view === 'water' ? <Droplets size={25} /> : ['employees', 'payroll'].includes(view) ? <Users size={25} /> : <Grape size={25} />}</div><div><p className="eyebrow">LOTES 467 E 463</p><h1>{title[0]}</h1><p>{title[1]}</p></div><div className="detail-actions">{view === 'fruit' && <button className="secondary" disabled={!saleRows.length} onClick={exportSales}><Download size={14} />Exportar Vendas</button>}{view === 'payroll' && <button className="secondary" disabled={!laborRows.length} onClick={exportPayroll}><Download size={14} />Exportar Folha</button>}{view === 'harvest' && onLegacy && <button className="secondary" onClick={onLegacy}>Registros Anteriores</button>}{view === 'employees' ? actions('employee', 'Novo Colaborador') : !['reports'].includes(view) && actions(view === 'costs' ? 'service' : view === 'planting' ? 'planting' : view === 'fruit' ? 'sale' : view === 'water' ? 'water' : view === 'payroll' ? 'labor' : view === 'fertilization' ? 'fertilization' : 'harvest', view === 'costs' ? 'Novo Serviço / Gasto' : view === 'planting' ? 'Adicionar Plantio' : view === 'harvest' ? 'Diário de Colheita' : 'Novo Registro')}</div></div>
    <div className="v-scope-note"><Leaf size={15} />Cada lançamento pertence a uma válvula de um lote. A Válvula 01 do lote 467 é independente da Válvula 01 do lote 463.</div>
    <div className="v-filters"><Select label="Lote" values={['Todos', '467', '463']} value={lot} onChange={e => setLot(e.target.value)} /><Select label="Variedade" values={varieties} value={variety} onChange={e => setVariety(e.target.value)} />{!['planting', 'harvest', 'fertilization'].includes(view) && <Field label="Mês dos Registros" type="month" value={period} onChange={e => setPeriod(e.target.value)} />}{['employees', 'payroll'].includes(view) && <Select label="Tipo de Colaborador" values={['Todos', 'Fixo', 'Avulso']} value={employeeType} onChange={e => setEmployeeType(e.target.value)} />}{view === 'payroll' && <Select label="Profissional" values={[{ value: 'Todos', label: 'Todos' }, ...model.employees.map(e => ({ value: e.id, label: e.name }))]} value={employeeId} onChange={e => setEmployeeId(e.target.value)} />}{period && <button className="text-button" onClick={() => setPeriod('')}>Limpar Mês</button>}</div>
    {view === 'costs' ? <><Kpis items={[["Serviços Realizados", money(totals.services)], ['Gasto com Diesel', money(totals.diesel)], ['Mão de Obra Apontada', money(totals.labor)], ['Todos os Custos Realizados', money(totals.cost)]]} /><div className="v-action-strip">{actions('service', 'Registrar Serviço')}{actions('diesel', 'Registrar Diesel')}{actions('material', 'Outra Despesa')}{actions('labor', 'Apontar Mão de Obra')}</div><p className="v-muted">Serviços contratados e mão de obra interna são registros distintos. Registre a mesma execução apenas uma vez. Custos Gerais não são divididos automaticamente entre válvulas.</p>{table(records.filter(e => costKinds.includes(e.kind)))}</> : view === 'employees' ? <>
      <Kpis items={[["Colaboradores", model.employees.length], ['Fixos Ativos', activeEmployees.filter(e => e.type === 'Fixo').length], ['Avulsos Ativos', activeEmployees.filter(e => e.type === 'Avulso').length], ['Horas Registradas', `${number(stats(model.entries).hours)} h`]]} />
      <div className="v-employee-grid">{employeeRows.map(person => { const rows = model.entries.filter(e => e.kind === 'labor' && e.employeeId === person.id); const s = stats(rows); return <section className="panel v-employee" key={person.id}><div className="v-employee-title"><Photo name={person.name} document={person.photo} /><div><h2>{person.name}</h2><p>{person.role || 'Função não informada'} · {person.type}</p></div><button className="row-action" aria-label={`Editar ${person.name}`} onClick={() => setEditor({ kind: 'employee', employee: person })}><Pencil size={15} /></button></div><div className="v-mini-totals"><span>Horas <b>{number(s.hours)} h</b></span><span>Faltas <b>{rows.filter(r => r.attendance === 'Falta').length}</b></span><span>Apurado <b>{money(s.labor)}</b></span></div><p className="v-muted">{person.valveId && model.valves.some(v => v.id === person.valveId) ? `${valveName(model.valves.find(v => v.id === person.valveId))} · ${person.variety}` : person.variety ? `Todos os Lotes · ${person.variety}` : 'Vinculação Geral'}</p><p className="v-muted">{person.active === false ? 'Inativo · Histórico preservado' : `Pagamento ${person.paymentPeriod || 'Semanal'}`} · Diária: {money(person.dailyRate || 0)}</p><button className="text-button" onClick={() => onEmployeeProfile ? onEmployeeProfile(person.id) : setEditor({ kind: 'history', employee: person })}>Histórico Detalhado <ArrowRight size={14} /></button></section>; })}</div>{!employeeRows.length && <div className="panel empty">Cadastre os profissionais como Fixos ou Avulsos. Os registros de horas e serviços aparecerão no histórico.</div>}
    </> : view === 'payroll' ? <>
      <Kpis items={[["Horas Trabalhadas", `${number(laborTotals.hours)} h`], ['Valor Apurado', money(laborTotals.labor)], ['Diárias Inteiras / Meias', `${laborRows.filter(e => e.status === 'Realizado' && e.attendance !== 'Falta' && e.payMode === 'Diária' && numeric(e.days) === 1).length} / ${laborRows.filter(e => e.status === 'Realizado' && e.attendance !== 'Falta' && e.payMode === 'Diária' && numeric(e.days) === 0.5).length}`], ['Faltas Registradas', laborRows.filter(e => e.attendance === 'Falta').length]]} />
      <p className="v-muted">A folha utiliza os mesmos apontamentos do diário. Não há cobrança duplicada. Salário mensal cadastrado não é rateado automaticamente nas válvulas.</p><AttendanceSheet rows={laborRows} model={model} onEdit={entry => setEditor({ kind: 'labor', entry })} />{table(laborRows)}
    </> : view === 'fruit' ? <>
      <Kpis items={[["Caixas Vendidas", number(totals.boxes)], ['Peso Vendido', `${number(totals.soldKg)} kg`], ['Venda Líquida', money(totals.revenue)], ['A Receber', money(totals.outstanding)]]} />
      <section className="panel v-sales"><div className="panel-title"><div><h2>Controle de Vendas · ARGOFRUTA</h2><p>Entrada, semana, nota fiscal, variedade, peso, desconto e pagamento.</p></div></div><SalesTable rows={saleRows} model={model} onEdit={entry => setEditor({ kind: 'sale', entry })} onDelete={entry => setEditor({ kind: 'delete', entry })} onValve={openValve} /></section>
    </> : view === 'water' ? <><Kpis items={[["Volume Realizado", `${number(records.filter(e => e.kind === 'water' && e.status === 'Realizado').reduce((s, e) => s + numeric(e.quantity), 0))} m³`], ['Custo de Água', money(totals.water)], ['Registros', records.filter(e => e.kind === 'water').length], ['Válvulas', filteredValves.length]]} />{table(records.filter(e => e.kind === 'water'))}</> : view === 'reports' ? <>
      <Kpis items={[["Produção", `${number(totals.tonnes)} t`], ['Custo Apropriado', money(totals.cost)], ['Venda Líquida', money(totals.revenue)], ['Recebido', money(totals.received)]]} /><div className="panel"><div className="panel-title"><div><h2>Resultado por Válvula</h2><p>Custos realizados. Planejamentos ficam separados.</p></div><button className="secondary" onClick={() => downloadJSON(model)}><Download size={15} />Exportar Backup</button></div><div className="table-wrap"><table><thead><tr>{['Lote / Válvula', 'Variedade', 'Produção (t)', 'Insumos', 'Mão de Obra', 'Matéria-Prima', 'Água', 'Custo Total', 'Venda Líquida', 'Resultado'].map(t => <th key={t}>{t}</th>)}<th>Imprimir</th></tr></thead><tbody>{filteredValves.map(v => { const s = stats(records.filter(e => e.valveId === v.id)); return <tr key={v.id}><td><button className="v-link" onClick={() => openValve(v.id)}>{valveName(v)}</button></td><td>{v.variety}</td><td>{number(s.tonnes)}</td><td>{money(s.inputs)}</td><td>{money(s.labor)}</td><td>{money(s.materials)}</td><td>{money(s.water)}</td><td>{money(s.cost)}</td><td>{money(s.revenue)}</td><td className={s.revenue - s.cost < 0 ? 'negative' : 'positive'}>{money(s.revenue - s.cost)}</td><td><button className="text-button" onClick={() => setReportValveId(v.id)}>Imprimir Ficha</button></td></tr>; })}</tbody></table></div></div><p className="v-muted">Resultado = venda líquida menos custos realizados. Fluxo de caixa utiliza somente recebimentos e pagamentos confirmados. Peso colhido e peso vendido são registros distintos.</p><div className="v-backup"><button className="secondary" onClick={() => downloadJSON(model)}>Exportar Backup dos Lotes</button><button className="secondary" onClick={() => importRef.current.click()}>Importar Backup</button><input ref={importRef} type="file" accept="application/json,.json" hidden onChange={e => importBackup(e.target.files[0])} /><span>O backup contém os registros, sem os arquivos anexados. Baixe os anexos separadamente.</span></div>
    </> : <>
      <Kpis items={[["Lotes / Válvulas", `${new Set(filteredValves.map(v => v.lot)).size} / ${filteredValves.length}`], [view === 'planting' ? 'Plantios Registrados' : 'Produção Realizada', view === 'planting' ? records.filter(e => e.kind === 'planting').length : `${number(totals.tonnes)} t`], ['Custo Realizado', money(totals.cost)], [view === 'planting' ? 'Plantios Planejados' : view === 'fertilization' ? 'Aplicações Planejadas' : 'Caixas Vendidas', view === 'planting' ? records.filter(e => e.kind === 'planting' && e.status === 'Planejado').length : view === 'fertilization' ? records.filter(e => e.kind === 'fertilization' && e.status === 'Planejado').length : number(totals.boxes)]]} />
      <VineyardCalendar varietyFilter={view === 'planting' ? variety : 'Todas'} weatherLocation={weatherLocation} model={model} valves={filteredValves} only={view === 'planting' ? 'planting' : view === 'fertilization' ? 'fertilization' : null} onValve={openValve} onAdd={date => setEditor({ kind: view === 'planting' ? 'planting' : view === 'fertilization' ? 'fertilization' : 'harvest', date })} />
      {['planting', 'harvest'].includes(view) && <section className="panel v-registry"><div className="panel-title"><div><h2>Lotes e Válvulas</h2><p>Clique no número para abrir a ficha completa, mesmo sem registros no calendário.</p></div><span className="table-status">18 Válvulas Cadastradas</span></div>{['467', '463'].filter(l => lot === 'Todos' || l === lot).map(l => <div className="v-lot" key={l}><h3>Lote {l} <span>{filteredValves.filter(v => v.lot === l).length} válvulas</span></h3><div className="v-valve-grid">{filteredValves.filter(v => v.lot === l).map(v => { const s = stats(model.entries.filter(e => e.valveId === v.id)); return <button className={`v-valve ${v.variety === 'Sugar Crisp' ? 'sugar' : v.variety === 'Timpson' ? 'timpson' : ''}`} key={v.id} aria-label={`Abrir ${valveName(v)}`} onClick={() => openValve(v.id)}><strong>{valNumber(v)}</strong><span>{v.variety}</span><small>{number(s.tonnes)} t · {money(s.cost)}</small><ValveProgress model={model} valve={v} /></button>; })}</div></div>)}</section>}
      <section className="panel v-registers"><div className="panel-title"><div><h2>{view === 'planting' ? 'Plantios por Válvula' : view === 'fertilization' ? 'Aplicações de Adubação' : 'Diário Interno de Colheita'}</h2><p>{view === 'planting' ? 'Edite o plantio para ajustar a previsão, os insumos e os funcionários sem duplicar os custos.' : view === 'fertilization' ? 'Editar uma aplicação atualiza o calendário e a ficha da válvula.' : 'Cachos, produção e equipe do dia. Vendas ficam na área Fruta.'}</p></div></div>{table(records.filter(e => view === 'planting' ? e.kind === 'planting' : view === 'fertilization' ? e.kind === 'fertilization' : e.kind === 'harvest'))}</section>
    </>}
    {selected && <section ref={detailRef} className="panel v-valve-detail" aria-label={`Ficha ${valveName(selected)}`}><div className="v-detail-heading"><div><p className="eyebrow">FICHA DA VÁLVULA · DADOS INDEPENDENTES</p><h2>{valveName(selected)}</h2><p>{selected.variety} · {selected.area ? `${number(selected.area)} ha` : 'Área não informada'}</p></div><div className="v-detail-buttons"><button className="secondary" onClick={() => setEditor({ kind: 'valve', valve: selected })}><Pencil size={14} />Editar Válvula</button><button className="icon-button" aria-label="Fechar ficha" onClick={() => setSelectedId(null)}><X size={18} /></button></div></div>
      <div className="v-tabs" role="tablist" aria-label="Informações da Válvula">{['Resumo', 'Plantio', 'Diário de Colheita', 'Insumos e Adubação', 'Mão de Obra', 'Vendas', 'Custos e Serviços', 'Anotações'].map(t => <button role="tab" aria-selected={tab === t} key={t} onClick={() => setTab(t)}>{t}</button>)}</div>
      <div className="v-detail-content">{tab === 'Resumo' ? <><Kpis items={[["Produção", `${number(valveStats.tonnes)} t`], ['Caixas Vendidas', number(valveStats.boxes)], ['Custo Realizado', money(valveStats.cost)], ['Venda Líquida', money(valveStats.revenue)]]} /><div className="v-summary-grid"><div><h3>Custos da Válvula</h3>{[['Insumos e Adubação', valveStats.inputs], ['Mão de Obra', valveStats.labor], ['Matéria-Prima / Outros', valveStats.materials], ['Serviços', valveStats.services], ['Diesel', valveStats.diesel], ['Água', valveStats.water], ['Custos Planejados', valveStats.plannedCost]].map(([l, v]) => <p key={l}><span>{l}</span><strong>{money(v)}</strong></p>)}</div><div><h3>Planejamento</h3><p><span>Previsão de Poda</span><strong>{selected.pruningDate ? shortDate(selected.pruningDate) : 'Não Informada'}</strong></p><p><span>Previsão de Colheita{latestPlanting ? ' (Plantio)' : ''}</span><strong>{harvestForecast ? shortDate(harvestForecast) : 'Não Informada'}</strong></p><p><span>Horas de Mão de Obra</span><strong>{number(valveStats.hours)} h</strong></p><p><span>Recebido / A Receber</span><strong>{money(valveStats.received)} / {money(valveStats.outstanding)}</strong></p><p className="v-long-text">{selected.notes || 'Sem observações cadastradas.'}</p></div></div><div className="v-action-strip">{actions('pruning', 'Registrar Poda')}{actions('note', 'Nova Anotação')}</div></> : <><div className="v-action-strip">{tab === 'Plantio' ? actions('planting', 'Adicionar Plantio') : tab === 'Diário de Colheita' ? actions('harvest', 'Diário de Colheita') : tab === 'Insumos e Adubação' ? <>{actions('input', 'Registrar Insumo')}{actions('fertilization', 'Programar Adubação')}</> : tab === 'Mão de Obra' ? actions('labor', 'Registrar Trabalho') : tab === 'Vendas' ? actions('sale', 'Registrar Venda') : tab === 'Custos e Serviços' ? <>{actions('service', 'Registrar Serviço')}{actions('diesel', 'Registrar Diesel')}{actions('material', 'Registrar Custo')}</> : actions('note', 'Nova Anotação')}</div>{tab === 'Vendas' ? <SalesTable rows={valveEntries.filter(e => e.kind === 'sale')} model={model} onEdit={entry => setEditor({ kind: 'sale', entry })} onDelete={entry => setEditor({ kind: 'delete', entry })} onValve={openValve} /> : table(valveEntries.filter(e => ({ 'Plantio': ['planting'], 'Diário de Colheita': ['harvest'], 'Insumos e Adubação': ['input', 'fertilization'], 'Mão de Obra': ['labor'], 'Custos e Serviços': ['water', 'material', 'service', 'diesel'], 'Anotações': ['note', 'pruning'] })[tab]?.includes(e.kind)), true)}</>}
      </div></section>}
    {!hideActivity && <RecentActivity model={model} legacy={legacyActivity} modules={view === 'reports' ? undefined : view === 'costs' ? ['costs', 'transactions'] : [view === 'fruit' ? 'sales' : ['employees', 'payroll'].includes(view) ? 'hr' : view === 'fertilization' ? 'inventory' : view]} />}
    {reportValveId && <ValveReport valve={model.valves.find(v => v.id === reportValveId)} model={model} period={period} onClose={() => setReportValveId('')} />}
    {notice && <p className="v-notice" role="status">{notice}</p>}
    {editor && !['employee', 'valve', 'delete', 'history', 'import'].includes(editor.kind) && <EntryEditor key={`${editor.kind}:${editor.entry?.id || 'new'}`} editor={editor} model={model} onSave={saveEntry} onClose={() => setEditor(null)} />}
    {editor?.kind === 'valve' && <ValveEditor valve={editor.valve} onClose={() => setEditor(null)} onSave={row => { onChange(p => ({ ...p, valves: p.valves.map(v => v.id === row.id ? row : v) })); setEditor(null); setNotice('Ficha da válvula atualizada.'); }} />}
    {editor?.kind === 'employee' && <EmployeeEditor model={model} employee={editor.employee} onClose={() => setEditor(null)} onSave={saveEmployee} />}
    {editor?.kind === 'history' && <Dialog wide title={`Histórico · ${editor.employee.name}`} onClose={() => setEditor(null)}><p className="v-muted">{editor.employee.type} · {editor.employee.role || 'Sem função cadastrada'} · {editor.employee.notes || 'Sem observações'}</p>{table(model.entries.filter(e => e.kind === 'labor' && e.employeeId === editor.employee.id))}</Dialog>}
    {editor?.kind === 'delete' && <Dialog title="Excluir Registro?" onClose={() => setEditor(null)}><p className="modal-description">O registro será removido e os totais serão recalculados.{['harvest', 'planting'].includes(editor.entry.kind) ? ' A equipe e os insumos vinculados a este registro também serão removidos.' : ''}</p><div className="modal-actions"><button className="secondary" onClick={() => setEditor(null)}>Cancelar</button><button className="primary danger" onClick={() => deleteEntry(editor.entry)}>Excluir Registro</button></div></Dialog>}
    {editor?.kind === 'import' && <Dialog title="Restaurar Backup dos Lotes?" onClose={() => setEditor(null)}><p className="modal-description">Esta ação substituirá as fichas, os registros, o RH e a agenda deste navegador pelo arquivo selecionado. Financeiro e estoque também serão restaurados quando estiverem incluídos no arquivo. Exporte uma cópia antes de continuar.</p><div className="modal-actions"><button className="secondary" onClick={() => downloadJSON(model)}>Exportar Cópia Atual</button><button className="primary" onClick={() => { onChange(() => editor.backup); setEditor(null); setSelectedId(null); setNotice('Backup restaurado.'); }}>Restaurar Backup</button></div></Dialog>}
  </div>;
}

function VineyardCalendar({ model, valves, only, onValve, onAdd, weatherLocation = PETROLINA, varietyFilter = 'Todas' }) {
  const [anchor, setAnchor] = useState(localDate());
  const weather = useWeather(weatherLocation, only === 'planting');
  const [forecastDate, setForecastDate] = useState(null);
  const forecastIndex = weather.data?.daily?.time.indexOf(forecastDate) ?? -1;
  const hasForecast = forecastIndex >= 0 && Number.isFinite(weather.data.daily.weather_code[forecastIndex]);
  const weatherStale = Boolean(weather.error || (weather.data && Date.now() - weather.data.fetchedAt > 20 * 60 * 1000));
  const [mode, setMode] = useState('Mensal');
  const date = parseDate(anchor); const year = date.getFullYear(); const month = date.getMonth();
  const first = new Date(year, month, 1); const last = new Date(year, month + 1, 0);
  const ids = new Set(valves.map(v => v.id));
  const events = model.entries.filter(e => ids.has(e.valveId) && (varietyFilter === 'Todas' || (e.variety || model.valves.find(v => v.id === e.valveId)?.variety) === varietyFilter) && (!only || e.kind === only)).map(e => ({ ...e, label: `${entryKinds[e.kind]} · ${e.name || ''}` }));
  if (!only || only === 'planting') for (const entry of model.entries.filter(e => e.kind === 'planting' && ids.has(e.valveId) && e.expectedHarvestDate && (varietyFilter === 'Todas' || (e.variety || model.valves.find(v => v.id === e.valveId)?.variety) === varietyFilter))) events.push({ id: `${entry.id}:forecast`, valveId: entry.valveId, variety: entry.variety, date: entry.expectedHarvestDate, label: 'Previsão de Colheita do Plantio', status: 'Planejado' });
  if (!only) for (const valve of valves) for (const [field, label] of [['pruningDate', 'Previsão de Poda'], ['harvestDate', 'Previsão de Colheita']]) if (valve[field]) events.push({ id: `${valve.id}:${field}`, valveId: valve.id, date: valve[field], label, status: 'Planejado' });
  const start = mode === 'Mensal' ? dayShift(localDate(first), -first.getDay()) : mode === 'Semanal' ? dayShift(anchor, -date.getDay()) : anchor;
  const count = mode === 'Mensal' ? Math.ceil((first.getDay() + last.getDate()) / 7) * 7 : mode === 'Semanal' ? 7 : 1;
  const days = Array.from({ length: count }, (_, i) => dayShift(start, i));
  function shift(direction) { setAnchor(mode === 'Mensal' ? localDate(new Date(year, month + direction, 1)) : dayShift(anchor, direction * (mode === 'Semanal' ? 7 : 1))); }
  return <section className="panel v-calendar"><div className="panel-title"><div><h2>{only === 'planting' ? 'Calendário de Plantio' : only ? 'Calendário de Adubação' : 'Calendário de Colheita'}</h2><p>Clique em V.01, V.02… para abrir todas as informações da válvula indicada.</p></div><div className="v-view-switch" aria-label="Visualização do Calendário">{['Diário', 'Semanal', 'Mensal'].map(v => <button key={v} aria-pressed={mode === v} onClick={() => setMode(v)}>{v}</button>)}</div></div><div className="v-calendar-toolbar"><div><button className="icon-button" aria-label="Período anterior" onClick={() => shift(-1)}><ChevronLeft size={17} /></button><strong>{mode === 'Mensal' ? date.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }) : `${shortDate(start)}${mode === 'Semanal' ? ` — ${shortDate(dayShift(start, 6))}` : ''}`}</strong><button className="icon-button" aria-label="Próximo período" onClick={() => shift(1)}><ChevronRight size={17} /></button><button className="text-button" onClick={() => setAnchor(localDate())}>Hoje</button></div><label className="v-field"><span className="sr-only">Ir para Data</span><input aria-label="Ir para Data" type="date" value={anchor} onChange={e => { if (e.target.value) setAnchor(e.target.value); }} /></label></div><div className={`v-calendar-scroll ${mode === 'Diário' ? 'v-day-mode' : ''}`}><div className="v-calendar-grid v-weekdays">{(mode === 'Diário' ? [date.toLocaleDateString('pt-BR', { weekday: 'long' })] : ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb']).map(day => <span key={day}>{day}</span>)}</div><div className="v-calendar-grid">{days.map(day => { const rawEvents = events.filter(e => e.date === day); const dayEvents = [...new Set(rawEvents.map(e => e.valveId))].map(valveId => { const grouped = rawEvents.filter(e => e.valveId === valveId); return { id: `${day}:${valveId}`, valveId, label: [...new Set(grouped.map(e => e.label))].join(' · '), status: grouped.every(e => e.status === 'Planejado') ? 'Planejado' : 'Realizado', count: grouped.length, variety: [...new Set(grouped.map(e => e.variety || model.valves.find(v => v.id === e.valveId)?.variety))].join(' / ') }; }); return <div key={day} className={`v-calendar-day ${day === localDate() ? 'v-today' : ''} ${mode === 'Mensal' && parseDate(day).getMonth() !== month ? 'v-other-month' : ''}`}><div className="v-day-header"><strong>{parseDate(day).getDate()}</strong>{only === 'planting' && <DayForecast day={day} weather={weather} onClick={() => setForecastDate(day)} />}<button aria-label={`Adicionar registro em ${day}`} onClick={() => onAdd(day)}><Plus size={12} /></button></div>{dayEvents.map(e => { const valve = model.valves.find(v => v.id === e.valveId); return <button key={e.id} className={`v-calendar-event ${e.status === 'Planejado' ? 'v-planned' : ''}`} aria-label={`${valveName(valve)} · ${e.label}`} onClick={() => onValve(e.valveId)}><strong>{valNumber(valve)} <small>Lote {valve.lot}</small></strong><span>{e.label}</span><small>{e.variety} · {e.count} registro{e.count !== 1 ? 's' : ''}</small></button>; })}{!dayEvents.length && mode === 'Diário' && <p className="empty">Sem registros nesta data. Use + para adicionar.</p>}</div>; })}</div></div><div className="v-calendar-legend"><span><i />Realizado</span><span><i className="v-planned-dot" />Planejado / Previsão</span><span>Previsões não entram nos custos realizados.</span></div>{only === 'planting' && <div className="v-calendar-weather-status"><span>{weather.loading ? 'Consultando o tempo de ' : 'Previsão para '}{weatherLocation.label} · {IS_DEMO ? 'Clima Simulado — Dados Fictícios' : 'Open-Meteo'}{weather.data ? ` · ${weatherStale ? 'Dados salvos' : 'Atualizado'} ${new Date(weather.data.fetchedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: weather.data.timezone })}` : ''}. Previsão disponível para até 16 dias; fora desse período, o ícone indica indisponibilidade.</span><button className="text-button" disabled={weather.loading} aria-label="Atualizar Tempo do Calendário" onClick={weather.refreshWeather}><RefreshCw size={13} />Atualizar Tempo</button></div>}{forecastDate && <Dialog title={`Previsão do Tempo · ${shortDate(forecastDate)}`} onClose={() => setForecastDate(null)}>{hasForecast ? <div className="v-daily-forecast"><WeatherIcon code={weather.data.daily.weather_code[forecastIndex]} size={42} /><h3>{describeWeather(weather.data.daily.weather_code[forecastIndex])}</h3><p>{weatherLocation.label}</p><dl><div><dt>Temperatura</dt><dd>{weather.data.daily.temperature_2m_min[forecastIndex] ?? '—'}°C a {weather.data.daily.temperature_2m_max[forecastIndex] ?? '—'}°C</dd></div><div><dt>Chance de Chuva</dt><dd>{weather.data.daily.precipitation_probability_max[forecastIndex] ?? '—'}%</dd></div><div><dt>Chuva Prevista</dt><dd>{weather.data.daily.precipitation_sum[forecastIndex] ?? '—'} mm</dd></div></dl><p className="v-muted">{IS_DEMO ? 'Exemplo fictício, sem previsão real.' : weatherStale ? 'Última consulta salva; atualização indisponível.' : 'Previsão atualizada.'} Fonte: {IS_DEMO ? 'Simulação Fictícia para Testes' : 'Open-Meteo'}. Não representa uma medição histórica ou uma estação dentro da fazenda.</p></div> : <p className="modal-description">{weather.loading ? 'A consulta está em andamento.' : 'Não há previsão atualizada disponível para esta data.'} Dias passados e datas além do alcance fornecido pela Open-Meteo não recebem valores estimados pelo app.</p>}</Dialog>}</section>;
}

function DayForecast({ day, weather, onClick }) {
  const index = weather.data?.daily?.time.indexOf(day) ?? -1;
  const available = index >= 0 && Number.isFinite(weather.data.daily.weather_code[index]);
  const stale = Boolean(weather.error || (weather.data && Date.now() - weather.data.fetchedAt > 20 * 60 * 1000));
  const label = available ? `${describeWeather(weather.data.daily.weather_code[index])} · ${weather.data.daily.temperature_2m_min[index] ?? '—'}° a ${weather.data.daily.temperature_2m_max[index] ?? '—'}° · chuva ${weather.data.daily.precipitation_probability_max[index] ?? '—'}%${stale ? ' · consulta salva' : ''}` : weather.loading ? 'Consultando previsão' : 'Previsão indisponível';
  return <button type="button" className={`v-day-weather ${available ? '' : 'v-weather-unavailable'}`} title={`${shortDate(day)} · ${label}`} aria-label={`Tempo em ${day}: ${label}`} onClick={onClick}>{available ? <WeatherIcon code={weather.data.daily.weather_code[index]} size={17} /> : <CloudSun size={17} />}</button>;
}

function EntryTable({ rows, model, onEdit, onDelete, onValve }) {
  return <div className="table-wrap"><table><thead><tr>{['Data', 'Lote / Válvula', 'Tipo / Descrição', 'Profissional / Quantidade', 'Situação', 'Custo / Valor', 'Ações'].map(s => <th key={s}>{s}</th>)}</tr></thead><tbody>{[...rows].sort((a, b) => b.date.localeCompare(a.date)).map(row => { const valve = model.valves.find(v => v.id === row.valveId) || { id: '' }; const person = model.employees.find(e => e.id === row.employeeId); return <tr key={row.id}><td>{shortDate(row.date)}</td><td><button className="v-link" onClick={() => onValve(valve.id)}>{valveName(valve)}</button><small className="v-cell-sub">{row.variety || valve.variety || ''}</small></td><td><strong>{row.name || entryKinds[row.kind]}</strong><small className="v-cell-sub">{entryKinds[row.kind]}{row.inputType ? ` · ${row.inputType}` : ''}{row.notes ? ` · ${row.notes}` : ''}</small></td><td>{row.kind === 'labor' ? <>{person?.name || row.name}<small className="v-cell-sub">{row.attendance} · {number(row.hours)} h · {row.payMode === 'Diária' ? `${number(row.days)} diária` : 'Por Hora'} · {row.job}</small></> : row.kind === 'planting' ? <>{number(row.plantQuantity)} mudas<small className="v-cell-sub">{row.expectedHarvestDate ? `Colheita prevista: ${shortDate(row.expectedHarvestDate)}` : 'Sem previsão'}</small><small className="v-cell-sub">{model.entries.filter(e => e.groupId === row.id && e.kind === 'input').length} insumos · {model.entries.filter(e => e.groupId === row.id && e.kind === 'labor').length} profissionais</small></> : row.kind === 'harvest' ? <>{number(row.bunches)} cachos<small className="v-cell-sub">{number(row.kilograms)} kg · {number(row.boxes)} caixas</small></> : row.kind === 'sale' ? `${number(row.boxes)} caixas · ${number(row.kilograms)} kg` : row.quantity !== undefined ? `${number(row.quantity)} ${row.unit || ''}` : row.frequency || '—'}</td><td><span className={`table-status ${row.status === 'Planejado' ? 'warning' : ''}`}>{row.status}</span>{row.paymentStatus && <small className="v-cell-sub">{row.paymentStatus}</small>}</td><td>{row.kind === 'planting' ? money(model.entries.filter(e => e.groupId === row.id).reduce((s, e) => s + costOf(e), 0)) : row.kind === 'sale' ? money(saleValues(row).net) : costKinds.includes(row.kind) ? money(costOf(row)) : '—'}</td><td><div className="row-actions"><button className="row-action" aria-label={`Editar registro ${row.id}`} title="Editar Registro" onClick={() => onEdit(row)}><Pencil size={14} /></button><button className="row-action delete-action" aria-label={`Excluir registro ${row.id}`} title="Excluir Registro" onClick={() => onDelete(row)}><Trash2 size={14} /></button></div></td></tr>; })}</tbody></table>{!rows.length && <p className="empty">Nenhum registro neste período. Cadastre um lançamento para começar.</p>}</div>;
}
function SalesTable({ rows, model, onEdit, onDelete, onValve }) {
  return <div className="table-wrap"><table className="v-sales-table"><thead><tr>{['Entrada', 'Semana', 'Comprador', 'Nº NF', 'Lote / Válvula', 'Variedade / Descrição', 'Caixas', 'Quant. kg', 'Preço / Base', 'Valor Bruto', 'Desconto', 'Valor Líquido', 'M.I / M.E', 'Situação', 'Pagamento', 'Ações'].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map(row => { const v = model.valves.find(v => v.id === row.valveId); const value = saleValues(row); return <tr key={row.id}><td>{shortDate(row.date)}</td><td>Sem. {isoWeek(row.date)}</td><td>{row.buyer}</td><td>{row.invoice || '—'}</td><td><button className="v-link" onClick={() => onValve(v.id)}>{valveName(v)}</button></td><td>{row.variety || v.variety}<small className="v-cell-sub">{row.name}</small></td><td>{number(row.boxes)}</td><td>{number(row.kilograms)}</td><td>{money(row.unitPrice)} / {row.priceBasis === 'Caixa' ? 'cx' : 'kg'}</td><td>{money(value.gross)}</td><td>{number(row.discountPercent)}%<small className="v-cell-sub">{money(value.discount)}</small></td><td><strong>{money(value.net)}</strong></td><td>{row.market || '—'}</td><td>{row.status}</td><td>{row.paymentStatus}<small className="v-cell-sub">{row.paymentDate ? shortDate(row.paymentDate) : row.dueDate ? `Venc. ${shortDate(row.dueDate)}` : ''}</small></td><td><div className="row-actions"><button className="row-action" aria-label={`Editar venda ${row.id}`} onClick={() => onEdit(row)}><Pencil size={14} /></button><button className="row-action delete-action" aria-label={`Excluir venda ${row.id}`} onClick={() => onDelete(row)}><Trash2 size={14} /></button></div></td></tr>; })}</tbody></table>{!rows.length && <p className="empty">Nenhuma venda cadastrada. Os números das imagens não foram importados.</p>}</div>;
}
function AttendanceSheet({ rows, model, onEdit }) {
  const dates = [...new Set(rows.map(r => r.date))].sort(); const ids = [...new Set(rows.map(r => r.employeeId))];
  return <section className="panel v-attendance"><div className="panel-title"><div><h2>Apontamento por Dia</h2><p>Clique nas horas para editar. Falta é registrada explicitamente; dia sem lançamento não conta como falta.</p></div></div><div className="table-wrap"><table><thead><tr><th>Profissional</th>{dates.map(d => <th key={d}>{shortDate(d)}</th>)}<th>Horas</th><th>Valor Apurado</th></tr></thead><tbody>{ids.map(id => { const person = model.employees.find(e => e.id === id); const personal = rows.filter(r => r.employeeId === id); const s = stats(personal); return <tr key={id}><td><strong>{person?.name || 'Profissional não informado'}</strong><small className="v-cell-sub">{person?.type}</small></td>{dates.map(d => <td key={d}>{personal.filter(r => r.date === d).map(r => <button className="v-attendance-cell" key={r.id} onClick={() => onEdit(r)}>{r.attendance === 'Falta' ? 'Falta' : `${number(r.hours)} h`}<small>{r.payMode === 'Diária' ? `${number(r.days)} diária` : 'Hora'} · {r.status}</small></button>)}</td>)}<td>{number(s.hours)} h</td><td>{money(s.labor)}</td></tr>; })}</tbody></table>{!rows.length && <p className="empty">Os profissionais do diário e dos apontamentos de trabalho aparecerão nesta folha.</p>}</div></section>;
}

function ValveEditor({ valve, onSave, onClose }) {
  return <Dialog title={`Editar ${valveName(valve)}`} onClose={onClose}><form onSubmit={e => { e.preventDefault(); const values = Object.fromEntries(new FormData(e.currentTarget)); onSave({ ...valve, ...values }); }}><p className="v-muted">Lote e número identificam esta válvula. Alterar a variedade preserva os lançamentos vinculados.</p><Select label="Variedade da Válvula" name="variety" values={VARIETIES} defaultValue={valve.variety} /><div className="form-row"><Field label="Área (ha)" name="area" type="number" defaultValue={valve.area} /><Field label="Número de Plantas" name="vines" type="number" step="1" defaultValue={valve.vines} /></div><Field label="Previsão de Poda" name="pruningDate" type="date" defaultValue={valve.pruningDate} /><Field label="Previsão de Colheita" name="harvestDate" type="date" defaultValue={valve.harvestDate} /><label className="v-field">Observações da Válvula<textarea name="notes" maxLength={4000} defaultValue={valve.notes} /></label><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" type="submit">Salvar Válvula</button></div></form></Dialog>;
}
function EmployeeEditor({ model, employee = {}, onSave, onClose }) {
  const [scope, setScope] = useState(() => scopeFor(employee, model.valves));
  const [photo, setPhoto] = useState(null); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  return <Dialog title={employee.id ? 'Editar Colaborador' : 'Novo Colaborador'} onClose={onClose}><form onSubmit={async e => { e.preventDefault(); const row = Object.fromEntries(new FormData(e.currentTarget)); if (!row.name.trim()) return; setBusy(true); let savedPhoto = employee.photo; try { if (photo) { if (!photo.type.startsWith('image/')) throw new Error('Escolha uma imagem para a foto.'); savedPhoto = await saveDocument(photo); } } catch (e) { setError(e.message); setBusy(false); return; } onSave({ ...employee, ...row, ...scope, photo: savedPhoto, name: row.name.trim(), dailyRate: numeric(row.dailyRate), hourlyRate: numeric(row.hourlyRate), monthlySalary: numeric(row.monthlySalary), active: row.active === 'Ativo' }); }}><ValveSelectors valves={model.valves} value={scope} onChange={setScope} /><p className="v-muted">Vinculação padrão opcional. O profissional pode trabalhar em outras válvulas nos apontamentos.</p><div className="photo-editor"><Photo large name={employee.name || 'Novo'} document={employee.photo} /><Field label="Foto do Funcionário" type="file" accept="image/png,image/jpeg,image/webp" onChange={e => setPhoto(e.target.files[0] || null)} /></div><Field label="Nome do Profissional" name="name" required defaultValue={employee.name} /><div className="form-row"><Field label="Telefone" name="phone" type="tel" defaultValue={employee.phone} /><Field label="Data de Nascimento" name="birthDate" type="date" defaultValue={employee.birthDate} /></div><Field label="Endereço" name="address" defaultValue={employee.address} /><Field label="Contato de Emergência" name="emergencyContact" defaultValue={employee.emergencyContact} /><div className="form-row"><Select label="Tipo de Vínculo" name="type" values={['Fixo', 'Avulso']} defaultValue={employee.type || 'Avulso'} /><Field label="Função Principal" name="role" defaultValue={employee.role} /></div><Select label="Periodicidade de Pagamento" name="paymentPeriod" values={['Semanal', 'Quinzenal', 'Mensal', 'Por Diária', 'Por Hora', 'Por Serviço']} defaultValue={employee.paymentPeriod || 'Semanal'} /><div className="form-row"><Field label="Valor da Diária (R$)" name="dailyRate" type="number" step="0.01" defaultValue={employee.dailyRate || ''} /><Field label="Valor da Hora (R$)" name="hourlyRate" type="number" step="0.01" defaultValue={employee.hourlyRate || ''} /></div><Field label="Salário Mensal de Referência (R$)" name="monthlySalary" type="number" step="0.01" defaultValue={employee.monthlySalary || ''} /><p className="v-muted">O salário de referência não é somado automaticamente a cada diária. O rateio de mão de obra é informado nos apontamentos.</p><Field label="Data de Início" name="startDate" type="date" defaultValue={employee.startDate} /><Select label="Situação do Cadastro" name="active" values={['Ativo', 'Inativo']} defaultValue={employee.active === false ? 'Inativo' : 'Ativo'} /><label className="v-field">Observações do Profissional<textarea name="notes" maxLength={4000} defaultValue={employee.notes} /></label>{error && <p className="negative" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" type="submit" disabled={busy}>{busy ? 'Salvando…' : 'Salvar Colaborador'}</button></div></form></Dialog>;
}

function ValveProgress({ model, valve }) {
  const cycle = cropCycle(model, valve.id);
  return <span className="registry-progress" style={{ '--variety': varietyColors[cycle.variety] || '#246b45' }}>{cycle.progress === null ? <small>Sem Previsão de Colheita</small> : <><span className="vine-progress"><i style={{ width: `${cycle.progress}%` }} /></span><small>{cycle.progress}% · {cycle.month}</small></>}</span>;
}

function PlantingInputs({ inputs, setInputs }) {
  function update(index, field, value) { setInputs(previous => previous.map((row, i) => i === index ? { ...row, [field]: value } : row)); }
  return <><div className="v-crew-title"><h3>Insumos do Plantio</h3><button className="secondary" type="button" onClick={() => setInputs(rows => [...rows, { key: crypto.randomUUID(), name: '', inputType: 'Mudas', quantity: '', unit: 'un', unitPrice: '', paymentStatus: 'Pendente' }])}><Plus size={15} />Adicionar Insumo</button></div>{!inputs.length && <p className="v-muted">Inclua os produtos e as quantidades utilizados ou planejados para esta válvula.</p>}{inputs.map((row, index) => { const prefix = `Insumo ${index + 1} · `; return <fieldset className="v-crew-person" key={row.id || row.key}><legend>Insumo {index + 1}</legend><button type="button" className="v-remove-person" aria-label={`Remover insumo ${index + 1}`} onClick={() => setInputs(rows => rows.filter((_, i) => i !== index))}><X size={16} /></button><div className="v-labor-fields"><div className="form-row"><Field label={prefix + 'Produto'} value={row.name} required onChange={e => update(index, 'name', e.target.value)} /><Select label={prefix + 'Tipo de Insumo'} values={inputTypes} value={row.inputType || 'Outros'} onChange={e => update(index, 'inputType', e.target.value)} /></div><div className="form-row"><Field label={prefix + 'Quantidade'} type="number" min="0.001" required value={row.quantity} onChange={e => update(index, 'quantity', e.target.value)} /><Select label={prefix + 'Unidade'} values={['un', 'kg', 'L', 'g', 'mL', 'sc']} value={row.unit} onChange={e => update(index, 'unit', e.target.value)} /></div><div className="form-row"><Field label={prefix + 'Custo Unitário (R$)'} type="number" step="0.01" required value={row.unitPrice} onChange={e => update(index, 'unitPrice', e.target.value)} /><Select label={prefix + 'Pagamento'} values={['Pendente', 'Pago']} value={row.paymentStatus || 'Pendente'} onChange={e => update(index, 'paymentStatus', e.target.value)} /></div>{row.paymentStatus === 'Pago' && <Field label={prefix + 'Data do Pagamento'} type="date" required value={row.paymentDate || ''} onChange={e => update(index, 'paymentDate', e.target.value)} />}<div className="v-entry-preview">Subtotal: <strong>{money(costOf({ ...row, kind: 'input' }))}</strong></div></div></fieldset>; })}</>;
}

function LaborFields({ prefix = '', value, employees, onChange }) {
  const p = (key, next) => onChange({ ...value, [key]: next });
  function person(id) { const e = employees.find(e => e.id === id); onChange({ ...value, employeeId: id, name: e?.name || '', employeeType: e?.type, job: value.job || e?.role || 'Colheita', rate: value.payMode === 'Hora' ? e?.hourlyRate || '' : e?.dailyRate || '' }); }
  function timing(key, next) { const row = { ...value, [key]: next }; if (row.startTime && row.endTime) { const minutes = t => { const [h, m] = t.split(':').map(Number); return h * 60 + m; }; let duration = minutes(row.endTime) - minutes(row.startTime); if (duration < 0) duration += 1440; row.hours = Math.max(0, (duration - numeric(row.breakMinutes)) / 60); } onChange(row); }
  return <div className="v-labor-fields"><div className="form-row"><Select label={`${prefix}Profissional`} values={[{ value: '', label: 'Selecione o Profissional' }, ...employees.map(e => ({ value: e.id, label: `${e.name} · ${e.type}${e.active === false ? ' (Inativo)' : ''}` }))]} value={value.employeeId || ''} onChange={e => person(e.target.value)} required /><Select label={`${prefix}Presença`} values={['Presente', 'Falta', 'Falta Justificada']} value={value.attendance || 'Presente'} onChange={e => p('attendance', e.target.value)} /></div><Field label={`${prefix}Serviço / Função`} value={value.job || ''} onChange={e => p('job', e.target.value)} list="v-services" required /><datalist id={prefix ? undefined : 'v-services'}><option>Poda</option><option>Desbrota</option><option>Primeiro Amarrio</option><option>Segundo Amarrio</option><option>Colheita</option></datalist><div className="v-time-grid"><Field label={`${prefix}Entrada`} type="time" value={value.startTime || ''} onChange={e => timing('startTime', e.target.value)} /><Field label={`${prefix}Saída`} type="time" value={value.endTime || ''} onChange={e => timing('endTime', e.target.value)} /><Field label={`${prefix}Intervalo (min)`} type="number" max="1440" value={value.breakMinutes ?? ''} onChange={e => timing('breakMinutes', e.target.value)} /><Field label={`${prefix}Horas Trabalhadas`} type="number" max="24" value={value.hours ?? ''} onChange={e => p('hours', e.target.value)} required={value.attendance === 'Presente'} /></div><div className="form-row"><Select label={`${prefix}Forma de Cálculo`} values={['Diária', 'Hora']} value={value.payMode || 'Diária'} onChange={e => { const employee = employees.find(p => p.id === value.employeeId); onChange({ ...value, payMode: e.target.value, rate: e.target.value === 'Hora' ? employee?.hourlyRate || '' : employee?.dailyRate || '' }); }} />{value.payMode !== 'Hora' ? <Select label={`${prefix}Diária Trabalhada`} values={[{ value: 1, label: 'Diária Inteira (1)' }, { value: 0.5, label: 'Meia Diária (0,5)' }]} value={value.days ?? 1} onChange={e => p('days', e.target.value)} /> : <div />}</div><div className="form-row"><Field label={`${prefix}Valor da ${value.payMode === 'Hora' ? 'Hora' : 'Diária'} (R$)`} type="number" step="0.01" value={value.rate ?? ''} onChange={e => p('rate', e.target.value)} required /><Select label={`${prefix}Pagamento da Mão de Obra`} values={['Pendente', 'Pago']} value={value.paymentStatus || 'Pendente'} onChange={e => p('paymentStatus', e.target.value)} /></div><div className="form-row"><Field label={`${prefix}Extra (R$)`} type="number" step="0.01" value={value.extra || ''} onChange={e => p('extra', e.target.value)} /><Field label={`${prefix}Comissão (R$)`} type="number" step="0.01" value={value.commission || ''} onChange={e => p('commission', e.target.value)} /></div><div className="v-entry-preview">Custo Apurado: <strong>{money(costOf({ ...value, kind: 'labor' }))}</strong><span>Horas e meia diária são informadas separadamente; não presumimos a jornada.</span></div></div>;
}

function EntryEditor({ editor, model, onSave, onClose }) {
  const [row, setRow] = useState(() => ({ kind: editor.kind, valveId: editor.valveId || '', name: '', date: editor.date || localDate(), status: ['fertilization', 'planting'].includes(editor.kind) ? 'Planejado' : 'Realizado', unit: editor.kind === 'diesel' ? 'L' : editor.kind === 'service' ? 'Serviço' : editor.kind === 'water' ? 'm³' : 'kg', paymentStatus: 'Pendente', priceBasis: 'kg', buyer: 'ARGOFRUTA', discountPercent: 1.5, payMode: 'Diária', days: 1, attendance: 'Presente', job: editor.kind === 'planting' ? 'Plantio' : 'Colheita', frequency: 'Diária', ...editor.entry }));
  const [crew, setCrew] = useState(() => editor.entry ? model.entries.filter(e => e.groupId === editor.entry.id && e.kind === 'labor').map(e => ({ ...e })) : []);
  const [plantingInputs, setPlantingInputs] = useState(() => editor.entry ? model.entries.filter(e => e.groupId === editor.entry.id && e.kind === 'input').map(e => ({ ...e })) : []);
  const [error, setError] = useState('');
  const [attachment, setAttachment] = useState(null);
  const [saving, setSaving] = useState(false);
  const update = (key, value) => setRow(r => ({ ...r, [key]: value }));
  const field = (name, label, type = 'text', props = {}) => <Field name={name} label={label} type={type} value={row[name] ?? ''} onChange={e => update(name, e.target.value)} {...props} />;
  async function submit(e) {
    e.preventDefault(); setError('');
    if ((!['service', 'diesel', 'material'].includes(row.kind) || row.valveId) && !model.valves.some(v => v.id === row.valveId)) { setError('Selecione o lote e a válvula deste registro.'); return; }
    if (!['labor', 'harvest', 'planting'].includes(row.kind) && !row.name.trim()) { setError('Informe uma descrição válida para o registro.'); return; }
    if (row.kind === 'sale' && !row.buyer.trim()) { setError('Informe o comprador.'); return; }
    if (row.status === 'Planejado' && (['Pago', 'Recebido', 'Parcial'].includes(row.paymentStatus) || crew.some(p => p.paymentStatus === 'Pago') || plantingInputs.some(p => p.paymentStatus === 'Pago'))) { setError('Confirme o registro como Realizado antes de confirmar seu pagamento ou recebimento.'); return; }
    if (costKinds.includes(row.kind) && row.paymentStatus === 'Pago' && !row.paymentDate) { setError('Informe a data do pagamento confirmado.'); return; }
    if (row.kind === 'sale' && row.paymentStatus !== 'Pendente' && !row.paymentDate) { setError('Informe a data do recebimento confirmado.'); return; }
    if (row.kind === 'sale' && row.paymentStatus === 'Parcial' && (numeric(row.receivedAmount) <= 0 || numeric(row.receivedAmount) >= saleValues(row).net)) { setError('O recebimento parcial deve ser maior que zero e menor que o valor líquido.'); return; }
    if (row.kind === 'labor' && row.groupId && row.valveId === linkedParent?.valveId && row.variety === (linkedParent?.variety || v?.variety) && model.entries.some(e => e.id !== row.id && e.groupId === row.groupId && e.kind === 'labor' && e.employeeId === row.employeeId)) { setError('Este profissional já está na equipe desta operação. Edite o registro principal para revisar a equipe.'); return; }
    if (row.kind === 'labor' && !row.employeeId) { setError('Selecione um profissional cadastrado.'); return; }
    if (['harvest', 'planting'].includes(row.kind) && new Set(crew.map(c => c.employeeId)).size !== crew.length) { setError('Cada profissional deve aparecer uma única vez na equipe deste diário.'); return; }
    for (const person of crew) if (!person.employeeId || (person.paymentStatus === 'Pago' && !person.paymentDate)) { setError('Revise o profissional e a data dos pagamentos confirmados na equipe.'); return; }
    if (row.kind === 'planting' && (!row.expectedHarvestDate || row.expectedHarvestDate < row.date)) { setError('A previsão de colheita deve ser igual ou posterior à data do plantio.'); return; }
    if (row.kind === 'planting' && plantingInputs.some(input => !input.name.trim() || (input.paymentStatus === 'Pago' && !input.paymentDate))) { setError('Revise a descrição e a data dos insumos pagos.'); return; }
    const clean = { ...row, lot: model.valves.find(v => v.id === row.valveId)?.lot, name: row.name.trim() || entryKinds[row.kind] };
    if (linkedParent && (clean.valveId !== linkedParent.valveId || clean.variety !== (linkedParent.variety || v?.variety))) { clean.originGroupId = clean.groupId; delete clean.groupId; }
    for (const key of numFields) if (key in clean) clean[key] = numeric(clean[key]);
    if (clean.kind === 'labor' && clean.attendance !== 'Presente') clean.hours = 0;
    if (attachment) {
      setSaving(true);
      try { clean.invoiceDocument = await saveDocument(attachment); } catch (error) { setError(error.message); setSaving(false); return; }
    }
    onSave(clean, ['harvest', 'planting'].includes(row.kind) ? crew.map(person => { const value = { ...person }; for (const key of numFields) if (key in value) value[key] = numeric(value[key]); if (value.attendance !== 'Presente') value.hours = 0; return value; }) : undefined, row.kind === 'planting' ? plantingInputs.map(input => ({ ...input, name: input.name.trim(), quantity: numeric(input.quantity), unitPrice: numeric(input.unitPrice) })) : undefined);
  }
  const v = model.valves.find(v => v.id === row.valveId);
  const linkedParent = model.entries.find(entry => entry.id === row.groupId);
  const amounts = saleValues(row);
  return <Dialog wide={['harvest', 'planting'].includes(row.kind)} title={`${editor.entry ? 'Editar' : 'Novo Registro'} · ${entryKinds[row.kind]}`} onClose={onClose}><form onSubmit={submit}>
    <ValveSelectors valves={model.valves} value={scopeFor(row, model.valves)} required={!['service', 'diesel', 'material'].includes(row.kind)} onChange={scope => setRow(r => ({ ...r, ...scope }))} />
    {field('date', row.kind === 'sale' ? 'Data de Entrada / Venda' : 'Data do Registro', 'date', { required: true, disabled: Boolean(linkedParent) })}
    {v && <p className="v-binding">{valveName(v)} · {row.variety || v.variety}{row.kind === 'sale' ? ` · Semana ${isoWeek(row.date)}` : ''}</p>}
    {linkedParent && <p className="v-muted">Vinculado a {entryKinds[linkedParent.kind]}. Alterar lote, válvula ou variedade transforma este apontamento em um registro independente. Para mover a operação inteira, edite o registro principal.</p>}
    {['service', 'diesel', 'material'].includes(editor.kind) && !editor.entry && <Select label="Tipo de Gasto" values={[{ value: 'service', label: 'Serviço de Campo' }, { value: 'diesel', label: 'Diesel' }, { value: 'material', label: 'Outra Despesa' }]} value={row.kind} onChange={e => setRow(r => ({ ...r, kind: e.target.value, unit: e.target.value === 'diesel' ? 'L' : 'Serviço', quantity: '', unitPrice: '' }))} />}
    {row.kind !== 'labor' && field('name', row.kind === 'sale' ? 'Descrição / Classificação da Fruta' : row.kind === 'planting' ? 'Descrição do Plantio' : row.kind === 'harvest' ? 'Descrição do Diário' : row.kind === 'note' ? 'Título da Anotação' : 'Descrição / Produto', 'text', { required: !['harvest', 'planting'].includes(row.kind) })}
    {['input', 'fertilization'].includes(row.kind) && model.inventory?.length > 0 && <Select label="Produto do Estoque" values={[{ value: '', label: 'Outro / Sem Vínculo' }, ...model.inventory.map(item => ({ value: item.id, label: item.name }))]} value={row.inventoryId || ''} onChange={e => { const item = model.inventory.find(p => p.id === e.target.value); setRow(r => ({ ...r, inventoryId: item?.id || '', ...(item ? { name: item.name, unit: item.unit, unitPrice: item.price } : {}) })); }} />}
    {row.kind === 'input' && <Select label="Tipo de Insumo" values={inputTypes} value={row.inputType || 'Outros'} onChange={e => update('inputType', e.target.value)} />}
    {['input', 'fertilization', 'water'].includes(row.kind) && <><div className="form-row">{field('quantity', row.kind === 'water' ? 'Volume de Água (m³)' : 'Quantidade Aplicada', 'number', { required: true, min: 0.001 })}{row.kind !== 'water' && <Select label="Unidade do Produto" values={['kg', 'L', 'g', 'mL', 'un', 'sc']} value={row.unit} onChange={e => update('unit', e.target.value)} />}</div><div className="form-row">{field('unitPrice', `Custo por ${row.unit} (R$)`, 'number', { required: true, step: '0.01' })}{field('supplier', 'Fornecedor / Responsável')}</div>{row.kind !== 'water' && field('invoice', 'Número da Nota Fiscal')}</>}
    {['service', 'diesel'].includes(row.kind) && <>{row.kind === 'service' && <Select label="Tipo de Serviço" values={['Poda', 'Primeiro Amarrio', 'Segundo Amarrio', 'Desbrota', 'Raleio', 'Plantio', 'Colheita', 'Manutenção', 'Outro']} value={row.serviceType || 'Poda'} onChange={e => setRow(r => ({ ...r, serviceType: e.target.value, name: r.name || e.target.value }))} />}<div className="form-row">{field('quantity', row.kind === 'diesel' ? 'Litros de Diesel' : 'Quantidade de Serviço', 'number', { min: 0.001, required: true })}{row.kind === 'service' ? <Select label="Unidade do Serviço" values={['Serviço', 'Hora', 'Diária', 'Hectare']} value={row.unit} onChange={e => update('unit', e.target.value)} /> : field('equipment', 'Máquina / Equipamento')}</div>{field('unitPrice', row.kind === 'diesel' ? 'Preço por Litro (R$)' : 'Valor Unitário do Serviço (R$)', 'number', { step: '0.01', required: true })}{field('supplier', 'Fornecedor / Prestador de Serviço')}{field('invoice', 'Número da Nota / Comprovante')}</>}
    {row.kind === 'material' && <><Select label="Categoria do Custo" values={['Matéria-Prima', 'Custo Fixo Rateado', 'Combustível', 'Energia', 'Manutenção', 'Outro']} value={row.category || 'Matéria-Prima'} onChange={e => update('category', e.target.value)} />{field('amount', 'Valor do Custo (R$)', 'number', { required: true, step: '0.01' })}</>}
    {row.kind === 'harvest' && <><div className="form-row">{field('bunches', 'Quantidade de Cachos', 'number', { step: 1 })}{field('boxes', 'Caixas Colhidas', 'number', { step: 1 })}</div>{field('kilograms', 'Peso Colhido (kg)', 'number')}<p className="v-muted">Cachos, caixas e peso são medidas independentes. Toneladas são calculadas apenas pelo peso informado.</p></>}
    {row.kind === 'planting' && <><div className="form-row">{field('expectedHarvestDate', 'Previsão de Colheita do Plantio', 'date', { required: true, min: row.date })}{field('plantQuantity', 'Quantidade Plantada (mudas)', 'number', { step: 1 })}</div><PlantingInputs inputs={plantingInputs} setInputs={setPlantingInputs} /></>}
    {['harvest', 'planting'].includes(row.kind) && <><div className="v-crew-title"><h3>{row.kind === 'planting' ? 'Equipe do Plantio' : 'Equipe da Colheita'}</h3><button className="secondary" type="button" disabled={!model.employees.length} onClick={() => setCrew(c => [...c, { key: crypto.randomUUID(), employeeId: '', payMode: 'Diária', days: 1, attendance: 'Presente', hours: '', rate: '', job: row.kind === 'planting' ? 'Plantio' : 'Colheita', paymentStatus: 'Pendente' }])}><Plus size={15} />Adicionar Pessoa</button></div>{!model.employees.length && <p className="v-muted">Cadastre primeiro os profissionais em Colaboradores. Você pode salvar o registro e adicionar a equipe depois.</p>}{crew.map((person, i) => <fieldset className="v-crew-person" key={person.id || person.key}><legend>Pessoa {i + 1}</legend><button type="button" className="v-remove-person" aria-label={`Remover pessoa ${i + 1}`} onClick={() => setCrew(c => c.filter((_, index) => index !== i))}><X size={16} /></button><LaborFields prefix={`Pessoa ${i + 1} · `} value={person} employees={model.employees} onChange={value => setCrew(c => c.map((r, index) => index === i ? value : r))} />{person.paymentStatus === 'Pago' && <Field label={`Pessoa ${i + 1} · Data do Pagamento`} type="date" value={person.paymentDate || ''} required onChange={e => setCrew(c => c.map((r, index) => index === i ? { ...r, paymentDate: e.target.value } : r))} />}</fieldset>)}</>}
    {row.kind === 'planting' && <div className="v-entry-preview">Custo {row.status === 'Planejado' ? 'Planejado' : 'Realizado'} do Plantio: <strong>{money([...plantingInputs.map(e => ({ ...e, kind: 'input' })), ...crew.map(e => ({ ...e, kind: 'labor' }))].reduce((sum, e) => sum + costOf(e), 0))}</strong><span>Insumos e mão de obra são vinculados ao plantio e contabilizados uma única vez na válvula.</span></div>}
    {row.kind === 'labor' && <LaborFields value={row} employees={model.employees} onChange={setRow} />}
    {row.kind === 'sale' && <><div className="form-row">{field('buyer', 'Comprador', 'text', { required: true })}{field('invoice', 'Número da Nota Fiscal')}</div><div className="form-row">{field('kilograms', 'Peso Vendido (kg)', 'number', { required: row.priceBasis === 'kg', min: row.priceBasis === 'kg' ? 0.001 : 0 })}{field('boxes', 'Caixas Vendidas', 'number', { step: 1, required: row.priceBasis === 'Caixa', min: row.priceBasis === 'Caixa' ? 1 : 0 })}</div><div className="form-row"><Select label="Base do Preço" values={['kg', 'Caixa']} value={row.priceBasis} onChange={e => update('priceBasis', e.target.value)} />{field('unitPrice', 'Preço Unitário da Venda (R$)', 'number', { required: true, min: 0.01, step: '0.01' })}</div><div className="form-row">{field('discountPercent', 'Desconto (%)', 'number', { max: 100, required: true })}<Select label="M.I / M.E" values={['Não Informado', 'M.I', 'M.E']} value={row.market || 'Não Informado'} onChange={e => update('market', e.target.value)} /></div><div className="v-sale-preview"><span>Valor Bruto <b>{money(amounts.gross)}</b></span><span>Desconto <b>{money(amounts.discount)}</b></span><span>Valor Líquido <b>{money(amounts.net)}</b></span></div><Select label="Situação do Recebimento" values={['Pendente', 'Recebido', 'Parcial']} value={row.paymentStatus} onChange={e => update('paymentStatus', e.target.value)} />{row.paymentStatus === 'Parcial' && field('receivedAmount', 'Valor Já Recebido (R$)', 'number', { min: 0.01, step: '0.01', required: true })}{field('dueDate', 'Vencimento / Previsão de Recebimento', 'date')}{row.paymentStatus !== 'Pendente' && field('paymentDate', 'Data do Recebimento', 'date', { required: true })}</>}
    {row.kind === 'note' && <Select label="Tipo de Anotação" values={['Diária', 'Semanal']} value={row.frequency} onChange={e => update('frequency', e.target.value)} />}
    <Select label="Situação do Registro" values={statusOptions} value={row.status} onChange={e => update('status', e.target.value)} />
    {costKinds.includes(row.kind) && row.kind !== 'labor' && <Select label="Situação do Pagamento" values={['Pendente', 'Pago']} value={row.paymentStatus} onChange={e => update('paymentStatus', e.target.value)} />}
    {costKinds.includes(row.kind) && row.paymentStatus !== 'Pago' && field('dueDate', 'Previsão de Pagamento', 'date')}
    {costKinds.includes(row.kind) && row.paymentStatus === 'Pago' && field('paymentDate', 'Data do Pagamento', 'date', { required: true })}
    {costKinds.includes(row.kind) && row.kind !== 'labor' && <div className="v-entry-preview">Custo {row.status === 'Planejado' ? 'Planejado' : 'Realizado'}: <strong>{money(costOf(row))}</strong></div>}
    {['input', 'fertilization', 'material', 'sale', 'service', 'diesel'].includes(row.kind) && <div className="v-document-field"><label className="v-field">Anexar Nota Fiscal / Comprovante<input aria-label="Anexar Nota Fiscal / Comprovante" type="file" accept="application/pdf,image/png,image/jpeg,image/webp" onChange={e => setAttachment(e.target.files[0] || null)} /></label><p className="v-muted">PDF ou imagem de até 5 MB. O arquivo fica somente neste navegador. O backup JSON inclui os registros, mas não os arquivos anexados.</p>{row.invoiceDocument && <div className="v-document-actions"><button className="text-button" type="button" onClick={() => openDocument(row.invoiceDocument).catch(error => setError(error.message))}>Baixar {row.invoiceDocument.name}</button><button className="text-button negative" type="button" onClick={() => update('invoiceDocument', null)}>Desvincular Anexo</button></div>}</div>}
    <label className="v-field">Observações / Anotações<textarea value={row.notes || ''} maxLength={6000} onChange={e => update('notes', e.target.value)} /></label>{error && <p className="negative" role="alert">{error}</p>}<div className="modal-actions"><button className="secondary" type="button" onClick={onClose}>Cancelar</button><button className="primary" type="submit" disabled={saving}><Check size={15} />{saving ? 'Salvando Anexo…' : 'Salvar Registro'}</button></div>
  </form></Dialog>;
}

export { Dialog, Field, Select, Kpis };
